contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount == 10);
        require(address(this).balance >= amount);

        uint balBefore = address(c).balance;
        uint potBefore = c.pot();

        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;
        uint potAfter = c.pot();

        // The same pseudo-random formula the contract uses decides win/loss.
        uint random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty, address(this)))) % 2;

        if (!reverted && random == 0) {
            // Win: fee of 1 wei goes to the bank (this contract), pot is paid out and reset.
            assert(balBefore + amount >= 1 && balAfter == balBefore + amount - potBefore - amount - 1 + potBefore && potAfter == 0);
        } else if (!reverted) {
            // Loss: only the ticket is kept.
            assert(balAfter == balBefore + amount && potAfter == potBefore + amount);
        } else {
            assert(balAfter == balBefore && potAfter == potBefore);
        }
    }

    receive() external payable {}
}

